package com.bank.components;

import java.util.logging.Logger;

// Counts connected account clusters with Union-Find (path compression + rank).
public class ClusterCounter {

    private static final Logger log = Logger.getLogger(ClusterCounter.class.getName());

    private int[] parent;
    private int[] rank;
    private int count;

    public int countComponents(int n, int[][] edges) {
        parent = new int[n];
        rank = new int[n];
        count = n;                       // each node its own component
        for (int i = 0; i < n; i++) parent[i] = i;

        for (int[] e : edges) {
            union(e[0], e[1]);
        }
        log.info("Nodes=" + n + " edges=" + edges.length + " -> components=" + count);
        return count;
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path compression (halving)
            x = parent[x];
        }
        return x;
    }

    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;            // already same component
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;                 // attach smaller rank under larger
        if (rank[ra] == rank[rb]) rank[ra]++;
        count--;                         // two components merged into one
    }
}
