package com.bank.components;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ComponentsDemo {

    private static final Logger log = Logger.getLogger(ComponentsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Account Cluster Count");
        // 6 accounts: clusters {0,1,2}, {3,4}, {5}
        int[][] links = {{0, 1}, {1, 2}, {3, 4}};
        ClusterCounter counter = new ClusterCounter();
        counter.countComponents(6, links); // expect 3
    }
}
